// ── State ─────────────────────────────────────────────────────────────────────
let selectedTaskId = null
let sidebarCollapsed = false
let moveTarget = null

window._selectedTaskId = null
window._selectedTaskName = null

// ── Board / sidebar selection ─────────────────────────────────────────────────
function selectBoard(el, name) {
  document.querySelectorAll('.board-row').forEach(r => r.classList.remove('active'))
  el.classList.add('active')
  document.getElementById('topbar-title').textContent = name
}

// ── Column filter ─────────────────────────────────────────────────────────────
function filterColumn(el) {
  const col = el.dataset.col
  const pills = document.querySelectorAll('#col-pills .cpill[data-col]')
  const groups = document.querySelectorAll('.col-group')

  if (col === 'all') {
    pills.forEach(p => p.classList.remove('on'))
    el.classList.add('on')
    groups.forEach(g => g.style.display = '')
    return
  }

  // Toggle individual column; remove 'all' highlight
  document.querySelector('#col-pills .cpill[data-col="all"]').classList.remove('on')
  el.classList.toggle('on')

  const active = [...document.querySelectorAll('#col-pills .cpill.on')].map(p => p.dataset.col).filter(Boolean)
  if (active.length === 0) {
    document.querySelector('#col-pills .cpill[data-col="all"]').classList.add('on')
    groups.forEach(g => g.style.display = '')
    return
  }
  groups.forEach(g => {
    g.style.display = active.includes(g.dataset.col) ? '' : 'none'
  })
}

// ── Sidebar search ────────────────────────────────────────────────────────────
function sbSearch(q) {
  const query = q.toLowerCase().trim()
  document.getElementById('sb-clear').style.display = q ? 'block' : 'none'

  const rows = document.querySelectorAll('.task-row')
  const groups = document.querySelectorAll('.col-group')
  let anyMatch = false

  if (!query) {
    rows.forEach(r => r.style.display = '')
    groups.forEach(g => {
      g.style.display = ''
      const lbl = g.querySelector('.slbl')
      if (lbl) lbl.style.display = ''
    })
    document.getElementById('sb-no-results').style.display = 'none'
    return
  }

  rows.forEach(r => {
    const data = (r.dataset.search || '') + ' ' + (r.querySelector('.tname')?.textContent || '')
    const match = data.toLowerCase().includes(query)
    r.style.display = match ? '' : 'none'
    if (match) anyMatch = true
  })

  groups.forEach(g => {
    const visible = [...g.querySelectorAll('.task-row')].some(r => r.style.display !== 'none')
    g.style.display = visible ? '' : 'none'
    const lbl = g.querySelector('.slbl')
    if (lbl) lbl.style.display = visible ? '' : 'none'
  })

  document.getElementById('sb-no-results').style.display = anyMatch ? 'none' : 'block'
}

function clearSbSearch() {
  document.getElementById('sb-search-input').value = ''
  sbSearch('')
}

// ── Task selection: the main event ───────────────────────────────────────────
function selectTask(id) {
  const task = TASKS[id]
  if (!task) return

  // Toggle off if already selected
  if (selectedTaskId === id) {
    closeDetail()
    return
  }

  selectedTaskId = id
  window._selectedTaskId = id
  window._selectedTaskName = task.name

  // ── Sidebar highlight ──
  document.querySelectorAll('.task-row').forEach(r => r.classList.remove('selected'))
  const tr = document.getElementById(`tr-${id}`)
  if (tr) tr.classList.add('selected')

  // ── Card highlight ──
  document.querySelectorAll('.kb-card').forEach(c => c.classList.remove('active'))
  const card = document.getElementById(`card-${id}`)
  if (card) card.classList.add('active')

  // ── Open detail panel ──
  document.getElementById('detail-panel').classList.add('open')

  // ── Populate detail ──
  populateDetail(task)
}

function populateDetail(task) {
  // Header
  document.getElementById('dp-title').textContent = task.name
  document.getElementById('dp-icon').className = `${task.icon}`
  document.getElementById('dp-icon').style.color = task.iconColor
  document.getElementById('dp-status-icon').style.background = `${task.iconColor}22`

  // Column badge
  document.getElementById('dp-col-name').textContent = task.col
  document.getElementById('dp-col-dot').style.background = task.colColor
  document.getElementById('dp-col-badge').style.background = `${task.colColor}1a`
  document.getElementById('dp-col-badge').style.borderColor = `${task.colColor}40`
  document.getElementById('dp-col-badge').style.color = task.colColor

  // Meta
  document.getElementById('dp-desc').textContent = task.desc
  document.getElementById('dp-priority').innerHTML = `<i class="fa-solid fa-flag" style="font-size:10px;"></i> ${task.priority}`
  document.getElementById('dp-priority').style.color = task.priorityColor
  document.getElementById('dp-assignee').innerHTML = `<i class="fa-solid fa-user" style="font-size:10px;color:#6366f1;"></i> ${task.assignee}`
  document.getElementById('dp-created').textContent = task.created
  document.getElementById('dp-updated').textContent = task.updated

  // Subtasks
  const stList = document.getElementById('dp-subtasks-list')
  document.getElementById('dp-st-count').textContent = task.subtasks.length
  if (task.subtasks.length) {
    stList.innerHTML = task.subtasks.map(st => `
      <div class="st-item">
        <i class="${st.done ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'}" style="font-size:11px;color:${st.done ? '#10b981' : '#4b5563'};flex-shrink:0;"></i>
        <span style="font-size:12px;color:${st.done ? '#6b7280' : '#9ca3af'};flex:1;${st.done ? 'text-decoration:line-through;' : ''}">${st.name}</span>
        <span style="font-size:10px;color:#4b5563;background:#1a1a1a;border-radius:8px;padding:1px 5px;">${st.col}</span>
      </div>
    `).join('')
  } else {
    stList.innerHTML = `<div style="font-size:11px;color:#4b5563;padding:6px 4px;text-align:center;">No subtasks — <span onclick="openAddSubtask(${task.id},'${task.name}')" style="color:#6366f1;cursor:pointer;">add one</span></div>`
  }

  // Files
  const filesSection = document.getElementById('dp-files-section')
  const filesList = document.getElementById('dp-files-list')
  if (task.files.length) {
    filesSection.style.display = 'block'
    filesList.innerHTML = task.files.map(f => `
      <div style="display:flex;align-items:center;gap:7px;padding:5px 8px;border-radius:6px;background:#242424;border:1px solid #2d2d2d;">
        <i class="fa-solid fa-file-code" style="font-size:11px;color:#6366f1;flex-shrink:0;"></i>
        <span style="font-size:12px;color:#9ca3af;flex:1;">${f}</span>
        <i class="fa-solid fa-external-link" style="font-size:10px;color:#4b5563;cursor:pointer;"></i>
      </div>
    `).join('')
  } else {
    filesSection.style.display = 'none'
  }

  // Messages
  const msgsSection = document.getElementById('dp-messages-section')
  const msgsList = document.getElementById('dp-messages-list')
  if (task.messages.length) {
    msgsSection.style.display = 'block'
    msgsList.innerHTML = task.messages.map(m => `
      <div style="background:#242424;border:1px solid #2d2d2d;border-radius:7px;padding:7px 9px;">
        <div style="display:flex;align-items:center;gap:5px;margin-bottom:4px;">
          <i class="fa-solid fa-user" style="font-size:9px;color:#6366f1;"></i>
          <span style="font-size:11px;font-weight:600;color:#818cf8;">${m.author}</span>
          <span style="font-size:10px;color:#4b5563;margin-left:auto;">${m.time}</span>
        </div>
        <div style="font-size:12px;color:#9ca3af;line-height:1.5;">"${m.text}"</div>
      </div>
    `).join('')
  } else {
    msgsSection.style.display = 'none'
  }

  // Activity
  document.getElementById('dp-activity').innerHTML = task.activity.map((a, i) => `
    <div style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;${i < task.activity.length - 1 ? 'border-bottom:1px solid #242424;' : ''}">
      <div style="width:22px;height:22px;border-radius:6px;background:${a.color}1a;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;">
        <i class="${a.icon}" style="font-size:9px;color:${a.color};"></i>
      </div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:11px;color:#9ca3af;line-height:1.5;">${a.text}</div>
        <div style="font-size:10px;color:#4b5563;margin-top:1px;">${a.time}</div>
      </div>
    </div>
  `).join('')

  // Update move modal task name reference
  document.getElementById('move-task-name').textContent = `Moving: ${task.name}`
}

