    }

    /* Chat messages area */
    .chat-area { flex: 1; overflow-y: auto; padding: 14px 16px; display: flex; flex-direction: column; gap: 12px; }

    /* Message bubbles - matching ChatSidebar style from codebase */
    .msg-ai {
      display: flex; gap: 10px; align-items: flex-start;
    }
    .msg-ai .bubble {
      background: #1a1a1a; border: 1px solid rgba(255,255,255,0.06); border-radius: 10px;
      padding: 10px 13px; max-width: 640px;
      font-size: 13px; color: rgba(255,255,255,0.82); line-height: 1.65;
      transition: border-color 150ms, background 150ms;
    }
    .msg-ai .bubble:hover { border-color: rgba(255,255,255,0.1); background: rgba(255,255,255,0.03); }
    .msg-user {
      display: flex; gap: 10px; align-items: flex-start; flex-direction: row-reverse;
    }
    .msg-user .bubble {
      background: rgba(99,102,241,0.14); border: 1px solid rgba(99,102,241,0.28); border-radius: 10px;
      padding: 10px 13px; max-width: 600px;
      font-size: 13px; color: #fff; line-height: 1.65;
      transition: border-color 150ms;
    }
    .msg-user .bubble:hover { border-color: rgba(99,102,241,0.45); }
    .avatar {
      width: 28px; height: 28px; border-radius: 7px; flex-shrink: 0;
      display: flex; align-items: center; justify-content: center; font-size: 12px;
    }
    .avatar.ai { background: rgba(99,102,241,0.18); color: #818cf8; }
    .avatar.user { background: rgba(99,102,241,0.28); color: #818cf8; }

    /* Code block */
    .code-block {
      background: #0d0d0d; border: 1px solid #2d2d2d; border-radius: 7px;
      padding: 10px 13px; font-family: 'Courier New', monospace; font-size: 12px;
      color: #a5d6ff; line-height: 1.6; overflow-x: auto; margin-top: 8px;
    }

    /* Input area */
    .input-area {
      border-top: 1px solid #2d2d2d; padding: 12px 14px; background: #1a1a1a; flex-shrink: 0;
    }
    .chat-input-wrap {
      background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
      border-radius: 11px; padding: 8px 12px; display: flex; flex-direction: column; gap: 8px;
      transition: border-color 150ms;
    }
    .chat-input-wrap:focus-within { border-color: rgba(99,102,241,0.4); }
    .chat-input-wrap textarea {
      background: transparent; border: none; outline: none; resize: none;
      color: #e5e7eb; font-size: 13px; line-height: 1.5;
      min-height: 40px; max-height: 120px;
    }
    .chat-input-wrap textarea::placeholder { color: #4b5563; }

    /* ── RIGHT DETAIL PANEL (Task Info) ── */
    #detail {
      width: 0; min-width: 0; overflow: hidden;
      background: #1a1a1a; border-left: 0px solid #2d2d2d;
      display: flex; flex-direction: column; height: 100vh;
      transition: width 220ms ease, min-width 220ms ease, border-width 200ms ease;
    }
    #detail.open { width: 300px; min-width: 300px; border-left-width: 1px; }

    /* Profile chips matching ChatSidebar profile section */
    .profile-chip {
      display: flex; align-items: center; gap: 7px;
      padding: 5px 8px; background: #242424; border: 1px solid #2d2d2d;
      border-radius: 8px; cursor: pointer; transition: border-color 120ms;
    }
    .profile-chip:hover { border-color: rgba(99,102,241,0.35); }
    .profile-avatar {
      width: 24px; height: 24px; border-radius: 50%; background: rgba(99,102,241,0.2);
      display: flex; align-items: center; justify-content: center; font-size: 10px; color: #818cf8; flex-shrink: 0;
    }

    /* Subtask item */
    .st-item {
      display: flex; align-items: center; gap: 7px; padding: 5px 8px;
      background: #222; border: 1px solid #2d2d2d; border-radius: 6px;
      cursor: pointer; transition: border-color 120ms; font-size: 12px; color: #9ca3af;
    }
    .st-item:hover { border-color: rgba(99,102,241,0.35); }

    /* File attachment item */
    .file-item {
      display: flex; align-items: center; gap: 7px; padding: 5px 8px;
      background: #1e1e1e; border: 1px solid #2d2d2d; border-radius: 6px;
      cursor: pointer; transition: border-color 120ms; font-size: 11px; color: #9ca3af;
    }
    .file-item:hover { border-color: rgba(99,102,241,0.3); }

    /* Mode badge (chat / task / pr) */
    .mode-badge {
      font-size: 10px; padding: 2px 7px; border-radius: 9px;
      display: inline-flex; align-items: center; gap: 4px;
    }

    /* Modals */
    .overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.6); backdrop-filter: blur(4px); z-index: 50; display: none; align-items: center; justify-content: center; }
    .overlay.show { display: flex; }
    .mbox { background: #1a1a1a; border: 1px solid #2d2d2d; border-radius: 13px; width: 400px; max-width: 95vw; }
    .mbox-sm { width: 340px; }
    .mhead { padding: 14px 16px; border-bottom: 1px solid #2d2d2d; display: flex; justify-content: space-between; align-items: center; }
    .mbody { padding: 14px 16px; display: flex; flex-direction: column; gap: 11px; }
    .mfoot { padding: 10px 16px; border-top: 1px solid #2d2d2d; display: flex; gap: 7px; justify-content: flex-end; }
    .flabel { font-size: 10px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 4px; display: block; }
    .finput { width: 100%; background: rgba(255,255,255,0.04); border: 1px solid #2d2d2d; border-radius: 7px; padding: 7px 11px; font-size: 13px; color: #e5e7eb; outline: none; transition: border-color 150ms; }
    .finput:focus { border-color: rgba(99,102,241,0.5); }

    /* New col CTA */
    .new-col-cta {
      background: #1a1a1a; border: 1px dashed #2d2d2d; border-radius: 12px;
      width: 160px; min-width: 160px; display: flex; flex-direction: column;
      align-items: center; justify-content: center; gap: 6px;
      padding: 20px 12px; cursor: pointer; color: #4b5563; font-size: 12px;
      transition: border-color 150ms, color 150ms;
    }
    .new-col-cta:hover { border-color: #6366f1; color: #818cf8; }

    /* View toggle buttons */
    .view-btn { padding: 4px 10px; border-radius: 6px; font-size: 11px; cursor: pointer; transition: background 120ms, color 120ms; border: 1px solid transparent; }
    .view-btn.active { background: rgba(99,102,241,0.15); border-color: rgba(99,102,241,0.35); color: #818cf8; }
    .view-btn:not(.active) { color: #6b7280; background: transparent; }
    .view-btn:not(.active):hover { color: #9ca3af; background: rgba(255,255,255,0.04); }
  </style>
</head>
<body>

<!-- ╔═══════════════════════════════════════════╗ -->
<!-- ║  LEFT SIDEBAR – Boards + Task List        ║ -->
<!-- ╚═══════════════════════════════════════════╝ -->
<aside id="sidebar">

  <!-- Header: board selector -->
  <div style="padding: 11px 10px 9px; border-bottom: 1px solid #2d2d2d; flex-shrink: 0;">

    <!-- Board list label -->
    <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 7px;">
      <span style="font-size: 10px; font-weight: 700; color: #4b5563; text-transform: uppercase; letter-spacing: 0.1em;">
        <i class="fa-brands fa-trello" style="color: #6366f1; margin-right: 4px;"></i>Boards
      </span>
      <button onclick="openModal('modal-board')" title="New board"
        style="background: transparent; border: none; color: #4b5563; cursor: pointer; padding: 2px 5px; border-radius: 4px; font-size: 10px; transition: color 120ms;"
        onmouseenter="this.style.color='#818cf8'" onmouseleave="this.style.color='#4b5563'">
        <i class="fa-solid fa-plus"></i>
      </button>
    </div>

    <!-- Boards -->
    <div style="display: flex; flex-direction: column; gap: 1px; margin-bottom: 9px;">
      <div class="board-row active" onclick="selectBoard(this, 'Sprint Q3 · 2025')">
        <i class="fa-solid fa-circle-dot" style="font-size: 8px; color: #6366f1; flex-shrink: 0;"></i>
        <span class="bname" style="color: #818cf8;">Sprint Q3 · 2025</span>
        <span style="font-size: 9px; color: #4b5563; background: #2d2d2d; border-radius: 9px; padding: 0 5px; flex-shrink: 0;">7</span>
      </div>
      <div class="board-row" onclick="selectBoard(this, 'Design Review')">
        <i class="fa-regular fa-circle" style="font-size: 8px; color: #4b5563; flex-shrink: 0;"></i>
        <span class="bname">Design Review</span>
        <span style="font-size: 9px; color: #4b5563; background: #2d2d2d; border-radius: 9px; padding: 0 5px; flex-shrink: 0;">3</span>
      </div>
      <div class="board-row" onclick="selectBoard(this, 'Backlog')">
        <i class="fa-regular fa-circle" style="font-size: 8px; color: #4b5563; flex-shrink: 0;"></i>
        <span class="bname">Backlog</span>
        <span style="font-size: 9px; color: #4b5563; background: #2d2d2d; border-radius: 9px; padding: 0 5px; flex-shrink: 0;">12</span>
      </div>
      <div class="board-row" onclick="selectBoard(this, 'Hotfixes')">
        <i class="fa-regular fa-circle" style="font-size: 8px; color: #4b5563; flex-shrink: 0;"></i>
        <span class="bname">Hotfixes</span>
        <span style="font-size: 9px; color: #4b5563; background: #2d2d2d; border-radius: 9px; padding: 0 5px; flex-shrink: 0;">2</span>
      </div>
      <!-- New board -->
      <button onclick="openModal('modal-board')"
        style="display: flex; align-items: center; gap: 5px; padding: 4px 8px; border-radius: 6px; background: transparent; border: 1px dashed #2d2d2d; color: #4b5563; font-size: 11px; cursor: pointer; margin-top: 2px; transition: border-color 120ms, color 120ms;"
        onmouseenter="this.style.borderColor='rgba(99,102,241,0.5)';this.style.color='#818cf8'"
        onmouseleave="this.style.borderColor='#2d2d2d';this.style.color='#4b5563'">
        <i class="fa-solid fa-plus" style="font-size: 9px;"></i> New Board
      </button>
    </div>

    <!-- Column filter -->
    <div class="slbl" style="margin-bottom: 5px;"><i class="fa-solid fa-table-columns" style="opacity:0.6;"></i> Columns</div>
    <div style="display: flex; flex-wrap: wrap; gap: 3px; margin-bottom: 9px;" id="col-pills">
      <span class="cpill on" data-col="all" onclick="filterCol(this)">All</span>
      <span class="cpill" data-col="todo" onclick="filterCol(this)"><span style="width:5px;height:5px;border-radius:50%;background:#6366f1;display:inline-block;"></span>To Do</span>
      <span class="cpill" data-col="wip" onclick="filterCol(this)"><span style="width:5px;height:5px;border-radius:50%;background:#f59e0b;display:inline-block;"></span>In Progress</span>
      <span class="cpill" data-col="done" onclick="filterCol(this)"><span style="width:5px;height:5px;border-radius:50%;background:#10b981;display:inline-block;"></span>Done</span>
      <span class="cpill" data-col="blocked" onclick="filterCol(this)"><span style="width:5px;height:5px;border-radius:50%;background:#ef4444;display:inline-block;"></span>Blocked</span>
      <span class="cpill" style="border-style:dashed;" onclick="openModal('modal-col')"><i class="fa-solid fa-plus" style="font-size:8px;"></i></span>
    </div>

    <!-- Search -->
    <div class="sb-search">
      <i class="fa-solid fa-magnifying-glass" style="font-size: 10px; color: #4b5563; flex-shrink: 0;"></i>
      <input id="sb-search" type="text" placeholder="Search tasks, messages, files…" oninput="doSearch(this.value)" />
      <button id="sb-clear" onclick="clearSearch()" style="display:none; background:transparent; border:none; color:#4b5563; cursor:pointer; padding:0;">
        <i class="fa-solid fa-xmark" style="font-size:10px;"></i>
      </button>
    </div>
  </div>

  <!-- Task list -->
  <div style="flex: 1; overflow-y: auto; padding: 7px 6px;" id="task-list-area">

    <div id="no-results" style="display:none; text-align:center; padding:24px 10px; color:#4b5563; font-size:11px;">
      <i class="fa-solid fa-search" style="font-size:18px; display:block; margin-bottom:6px; opacity:0.3;"></i>
      No tasks found
    </div>

    <!-- To Do -->
    <div class="col-group" data-col="todo">
      <div class="slbl" style="margin-top:3px; margin-bottom:2px;">
        <span style="width:5px;height:5px;border-radius:50%;background:#6366f1;display:inline-block;"></span>To Do
        <span style="color:#2d2d2d;">3</span>
        <div style="flex:1;"></div>
        <button onclick="openModal('modal-task'); setCol('To Do')" style="background:transparent;border:none;color:#4b5563;cursor:pointer;font-size:8px;padding:1px 3px;border-radius:3px;" title="Add task" onmouseenter="this.style.color='#818cf8'" onmouseleave="this.style.color='#4b5563'"><i class="fa-solid fa-plus"></i></button>
      </div>
      <div id="tl-todo">
        <div class="task-row" id="tr-1" data-id="1" data-search="implement auth flow oauth alice" onclick="selectTask(1)">
          <i class="fa-regular fa-circle-check" style="font-size:10px;color:#6366f1;flex-shrink:0;"></i>
          <span class="tname">Implement auth flow</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(1,'Implement auth flow')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
        <div class="task-row" id="tr-2" data-id="2" data-search="design token system figma colors" onclick="selectTask(2)">
          <i class="fa-regular fa-circle" style="font-size:10px;color:#4b5563;flex-shrink:0;"></i>
          <span class="tname">Design token system</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(2,'Design token system')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
        <div class="task-row" id="tr-3" data-id="3" data-search="write api docs readme openapi bob" onclick="selectTask(3)">
          <i class="fa-regular fa-circle" style="font-size:10px;color:#4b5563;flex-shrink:0;"></i>
          <span class="tname">Write API docs</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(3,'Write API docs')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
      </div>
    </div>

    <!-- In Progress -->
    <div class="col-group" data-col="wip">
      <div class="slbl" style="margin-top:8px; margin-bottom:2px;">
        <span style="width:5px;height:5px;border-radius:50%;background:#f59e0b;display:inline-block;"></span>In Progress
        <span style="color:#2d2d2d;">2</span>
        <div style="flex:1;"></div>
        <button onclick="openModal('modal-task'); setCol('In Progress')" style="background:transparent;border:none;color:#4b5563;cursor:pointer;font-size:8px;padding:1px 3px;border-radius:3px;" title="Add task" onmouseenter="this.style.color='#818cf8'" onmouseleave="this.style.color='#4b5563'"><i class="fa-solid fa-plus"></i></button>
      </div>
      <div id="tl-wip">
        <div class="task-row" id="tr-4" data-id="4" data-search="kanban drag drop dnd bob" onclick="selectTask(4)">
          <i class="fa-solid fa-circle-half-stroke" style="font-size:10px;color:#f59e0b;flex-shrink:0;"></i>
          <span class="tname">Kanban drag and drop</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(4,'Kanban drag and drop')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
        <div class="task-row" id="tr-5" data-id="5" data-search="unit test coverage vitest alice" onclick="selectTask(5)">
          <i class="fa-solid fa-circle-half-stroke" style="font-size:10px;color:#f59e0b;flex-shrink:0;"></i>
          <span class="tname">Unit test coverage</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(5,'Unit test coverage')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
      </div>
    </div>

    <!-- Done -->
    <div class="col-group" data-col="done">
      <div class="slbl" style="margin-top:8px; margin-bottom:2px;">
        <span style="width:5px;height:5px;border-radius:50%;background:#10b981;display:inline-block;"></span>Done
        <span style="color:#2d2d2d;">1</span>
      </div>
      <div>
        <div class="task-row" id="tr-6" data-id="6" data-search="setup ci pipeline github alice" onclick="selectTask(6)">
          <i class="fa-solid fa-circle-check" style="font-size:10px;color:#10b981;flex-shrink:0;"></i>
          <span class="tname" style="text-decoration:line-through;color:#6b7280;">Setup CI pipeline</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(6,'Setup CI pipeline')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
      </div>
    </div>

    <!-- Blocked -->
    <div class="col-group" data-col="blocked">
      <div class="slbl" style="margin-top:8px; margin-bottom:2px;">
        <span style="width:5px;height:5px;border-radius:50%;background:#ef4444;display:inline-block;"></span>Blocked
        <span style="color:#2d2d2d;">1</span>
      </div>
      <div>
        <div class="task-row" id="tr-7" data-id="7" data-search="database migration postgres charlie" onclick="selectTask(7)">
          <i class="fa-solid fa-circle-exclamation" style="font-size:10px;color:#ef4444;flex-shrink:0;"></i>
          <span class="tname">Database migration</span>
          <button class="add-st" onclick="event.stopPropagation();addSubtask(7,'Database migration')" title="Add subtask"><i class="fa-solid fa-plus"></i></button>
        </div>
      </div>
    </div>
  </div>

  <!-- Footer -->
  <div style="padding: 9px 8px; border-top: 1px solid #2d2d2d; flex-shrink: 0; background: #1a1a1a;">
    <button onclick="openModal('modal-task')"
      style="width:100%; display:flex; align-items:center; justify-content:center; gap:5px; padding:6px; border-radius:7px; background:rgba(99,102,241,0.12); border:1px solid rgba(99,102,241,0.25); color:#818cf8; font-size:12px; cursor:pointer; margin-bottom:6px; transition: background 150ms;"
      onmouseenter="this.style.background='rgba(99,102,241,0.2)'" onmouseleave="this.style.background='rgba(99,102,241,0.12)'">
      <i class="fa-solid fa-plus" style="font-size:9px;"></i> New Task
    </button>
    <button onclick="toggleSidebar()" id="sb-toggle"
      style="width:100%; display:flex; align-items:center; justify-content:center; gap:5px; padding:5px; border-radius:6px; background:transparent; border:1px solid #2d2d2d; color:#4b5563; font-size:11px; cursor:pointer; transition: background 120ms, color 120ms;"
      onmouseenter="this.style.background='rgba(255,255,255,0.03)';this.style.color='#9ca3af'"
      onmouseleave="this.style.background='transparent';this.style.color='#4b5563'">
      <i class="fa-solid fa-angle-left" id="sb-icon"></i>
      <span id="sb-label">Collapse</span>
    </button>
  </div>
</aside>

<!-- ╔═══════════════════════════════════════════╗ -->
<!-- ║  MAIN PANEL                               ║ -->
<!-- ╚═══════════════════════════════════════════╝ -->
<div id="main-panel">

  <!-- Top bar -->
  <div class="topbar">
    <!-- Sidebar toggle (when collapsed) -->
    <button id="expand-btn" onclick="toggleSidebar()" title="Expand sidebar"
      style="display:none; background:transparent; border:none; color:#4b5563; cursor:pointer; padding:4px 6px; border-radius:6px; margin-right:4px; transition: color 120ms;"
      onmouseenter="this.style.color='#9ca3af'" onmouseleave="this.style.color='#4b5563'">
      <i class="fa-solid fa-bars"></i>
    </button>

    <!-- View toggle: Board / Chat -->
    <div style="display: flex; gap: 3px; padding: 3px; background: rgba(255,255,255,0.04); border-radius: 8px;">
      <button class="view-btn" id="vbtn-board" onclick="switchView('board')">
        <i class="fa-solid fa-table-columns" style="margin-right:4px;"></i>Board
      </button>
      <button class="view-btn active" id="vbtn-chat" onclick="switchView('chat')">
        <i class="fa-solid fa-message" style="margin-right:4px;"></i>Chat
      </button>
    </div>

    <div style="flex:1;"></div>

    <!-- Task title (shown when task selected) -->
    <div id="topbar-task-info" style="display:none; align-items:center; gap:8px;">
      <div id="topbar-task-name" style="font-size:13px; font-weight:600; color:#e5e7eb; max-width:260px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">Task name</div>
      <div id="topbar-col-badge" style="font-size:10px; padding:2px 7px; border-radius:9px; background:rgba(99,102,241,0.12); border:1px solid rgba(99,102,241,0.25); color:#818cf8;">To Do</div>
    </div>

    <div style="flex:1;"></div>

    <button onclick="openModal('modal-col')"
      style="padding:5px 10px; border-radius:7px; background:rgba(255,255,255,0.04); border:1px solid #2d2d2d; color:#6b7280; font-size:11px; cursor:pointer; display:flex; align-items:center; gap:4px; transition: background 120ms, color 120ms;"
      onmouseenter="this.style.background='rgba(255,255,255,0.07)';this.style.color='#9ca3af'"
      onmouseleave="this.style.background='rgba(255,255,255,0.04)';this.style.color='#6b7280'">
      <i class="fa-solid fa-table-columns" style="font-size:9px;"></i> Column
    </button>
    <button onclick="openModal('modal-task')"
      style="padding:5px 12px; border-radius:7px; background:#6366f1; border:none; color:#fff; font-size:11px; font-weight:500; cursor:pointer; display:flex; align-items:center; gap:4px; transition: background 120ms;"
      onmouseenter="this.style.background='#4f46e5'" onmouseleave="this.style.background='#6366f1'">
      <i class="fa-solid fa-plus" style="font-size:9px;"></i> New Task
    </button>
    <!-- Detail toggle -->
    <button id="detail-toggle-btn" onclick="toggleDetail()" title="Task details"
      style="padding:5px 8px; border-radius:7px; background:transparent; border:1px solid #2d2d2d; color:#4b5563; font-size:11px; cursor:pointer; display:none; align-items:center; gap:4px; transition: background 120ms, color 120ms; margin-left:4px;"
      onmouseenter="this.style.background='rgba(255,255,255,0.05)';this.style.color='#9ca3af'"
      onmouseleave="this.style.background='transparent';this.style.color='#4b5563'">
      <i class="fa-solid fa-sidebar-flip"></i>
    </button>
  </div>

  <!-- ── BOARD VIEW ── -->
  <div id="view-board" style="flex:1; overflow-x:auto; overflow-y:hidden; padding:12px 14px; display:none; gap:12px; align-items:flex-start;">

    <!-- To Do -->
