// ── Board select ──────────────────────────────────────────────────────────────
function selectBoard(el, name) {
  document.querySelectorAll('.board-row').forEach(r => r.classList.remove('active'))
  el.classList.add('active')
}

// ── Column filter ─────────────────────────────────────────────────────────────
function filterCol(el) {
  const col = el.dataset.col
  document.querySelectorAll('#col-pills .cpill[data-col]').forEach(p => p.classList.remove('on'))

  if (col === 'all') {
    el.classList.add('on')
    document.querySelectorAll('.col-group').forEach(g => g.style.display = '')
    return
  }

  el.classList.add('on')
  document.querySelectorAll('.col-group').forEach(g => {
    g.style.display = g.dataset.col === col ? '' : 'none'
  })
}

// ── Search ────────────────────────────────────────────────────────────────────
function doSearch(q) {
  const query = q.toLowerCase().trim()
  document.getElementById('sb-clear').style.display = q ? 'block' : 'none'

  if (!query) {
    document.querySelectorAll('.task-row').forEach(r => r.style.display = '')
    document.querySelectorAll('.col-group').forEach(g => g.style.display = '')
    document.getElementById('no-results').style.display = 'none'
    return
  }

  let any = false
  document.querySelectorAll('.task-row').forEach(r => {
    const txt = (r.dataset.search || '') + ' ' + (r.querySelector('.tname')?.textContent || '')
    const match = txt.toLowerCase().includes(query)
    r.style.display = match ? '' : 'none'
    if (match) any = true
  })

  document.querySelectorAll('.col-group').forEach(g => {
    const vis = [...g.querySelectorAll('.task-row')].some(r => r.style.display !== 'none')
    g.style.display = vis ? '' : 'none'
  })

  document.getElementById('no-results').style.display = any ? 'none' : 'block'
}

function clearSearch() {
