    project(newVal, oldVal) {
      if (newVal?.codx_path !== oldVal?.codx_path) {
        this.projectChanged()
      }
    }
  },
  computed: {
    isMobile() {
      return this.$ui.isMobile
    },
    project() {
      return this.$project
    },
    kanban() {
      // Read from the kanban store which reads from activeProject.$state.kanban
      return this.$kanban.kanban
    },
    boards() {
      // Use kanban store's allBoards getter (already handles null boards, adds id/title)
      return this.$kanban.allBoards
        .filter(b => !this.selectedBoard || b.parent_id === this.selectedBoard)
    },
    selectedBoard() {
      return this.$kanban.activeBoard
    },
    activeBoard() {
      // Board is valid only if it exists in the kanban config
      return this.$kanban.activeKanbanBoard ? this.$kanban.activeBoard : null
    },
    showKanban() {
      return !this.activeChat && !this.showHistory && !!this.activeBoard
    },
    showKanbanList() {
      return !this.activeChat && !this.showHistory && !this.showKanban
    },
    activeChat() {
      return this.$ui.isMobile ? this.$chats.activeChat : null
    }
  },
  methods: {
    async projectChanged() {
      if (!this.project?.$state?.kanban) {
        await this.$storex.kanban.loadKanban(this.project)
      }
      this.selectBoard()
    },
    async selectBoard(board) {
      await this.$kanban.setActiveBoard(board)
    },
    showNewBoardModal() {
      this.editingBoard = {
        title: '',
        description: '',
        background: '',
        parent_id: this.activeBoard || null,
        columns: [],
        id: null
      }
      this.showBoardModal = true
    },
    onEditBoard(board) {
      const title = board?.title || this.activeBoard
      this.editingBoard = { title, ...this.kanban?.boards?.[title] }
      this.showBoardModal = true
    },
    closeBoardModal() {
      this.showBoardModal = false
      this.editingBoard = null
    },
    toggleBookmark({ title } = {}) {
      this.$kanban.toggleBookmark(title || this.activeBoard)
    },
    async onDeleteBoard(board) {
      await this.$kanban.deleteBoard(board)
      this.closeBoardModal()
    },
    onChatEditDone() {
      this.$chats.setActiveChat()
    },
    async setActiveChat(chat) {
      chat && await this.$chats.reloadChat(chat)
      this.$chats.setActiveChat(chat)
    },
  }
}
</script>

